import{readFile,writeFile}from'node:fs/promises';import assert from'node:assert/strict';import path from'node:path';import{createCanvas,loadImage}from'@napi-rs/canvas';
const dir=process.argv[2],rows=[];const px=async p=>{const im=await loadImage(await readFile(p)),q=createCanvas(im.width,im.height).getContext('2d');q.drawImage(im,0,0);return q.getImageData(0,0,im.width,im.height).data;};
const expected={lower:'db362ea1c2fd5a85e9ec2a00dab8a1d1ddf0398d1e814c85d1bb4f147eae065b',left:'433ee070c4a868b336687a58438066bcafef57af8e108316d74a487c1da77b65'};
for(const view of ['lower','left']){const a=JSON.parse(await readFile(path.join(dir,`stage32-candidate-${view}.json`))),b=JSON.parse(await readFile(path.join(dir,`stage32-transition-${view}.json`)));assert.equal(a.pngSha256,expected[view],'Frozen13d PNG changed');assert.equal(b.pngSha256,({lower:'38c9da07ffeb12b08b3275d0e826d8a71aee7905705bc2d02f44c89a6585bfdc',left:'ddc4c96f8d4bfadd880a91c1669e74037752bbc9133534d62a89a16f1a5294ef'})[view],'Scanline differs from exact previous point-query color candidate');for(const key of['camera','physicsSha256','battleSha256','sourceCanonicalSha256','vectorSHA','sourcePathHashes','runtimeSha256'])assert.deepEqual(b[key],a[key],key);const A=await px(path.join(dir,`stage32-candidate-${view}.png`)),B=await px(path.join(dir,`stage32-transition-${view}.png`));let changed=0,max=0,upper=0,alpha=0,aboveWalkRoadBuffer=0;for(let y=0;y<763;y++)for(let x=0;x<1331;x++){const k=(y*1331+x)*4,wy=(y-763/2)/.6+a.camera.y;let d=0;for(let j=0;j<4;j++)d=Math.max(d,Math.abs(A[k+j]-B[k+j]));if(A[k+3]!==B[k+3])alpha++;if(d){changed++;max=Math.max(max,d);if(wy<=1700)upper++;if(wy<=1380)aboveWalkRoadBuffer++;}}assert.equal(alpha,0);assert.equal(aboveWalkRoadBuffer,0);rows.push({view,changed,max,formerWholeUpperGateChanged:upper,alphaChanged:alpha,aboveWalkRoadBuffer,baselinePerf:a.performanceReport,candidatePerf:b.performanceReport,coverage:b.cacheStats.coverage,scope:'Bounded non-walk internal seam candidate. Old whole-upper exact is recorded, not claimed. Current BODY alpha and actual source roads/grass geometry preserved; final art and performance require review.'});}
await writeFile(path.join(dir,'coverage-comparison.json'),JSON.stringify(rows,null,2));console.log(JSON.stringify(rows.map(({baselinePerf,candidatePerf,...r})=>({...r,baselineCold:baselinePerf.coldRender,newCold:candidatePerf.coldRender,baselineWarm:baselinePerf.warmRender,newWarm:candidatePerf.warmRender}))));
